<?= view('components/page_start', ['pageTitle' => $pageTitle]) ?>
<section class="page-section"><div class="container-xl"><p class="eyebrow">Your picks</p><h1 class="section-title mb-5">Shopping cart</h1><?php if (session()->getFlashdata('success')): ?><div class="alert alert-success"><?= esc(session()->getFlashdata('success')) ?></div><?php endif; ?><?php if (session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-8"><div class="surface-card overflow-hidden"><?php if ($items === []): ?><div class="empty-state"><div><i class="fa-solid fa-bag-shopping mb-3"></i><h2 class="h4">Your cart is empty</h2><a class="btn btn-brand mt-3" href="/products">Browse products</a></div></div><?php else: ?><form action="/cart/update" method="post"><?php foreach ($items as $item): ?><div class="cart-item d-flex flex-wrap align-items-center gap-3"><div class="cart-thumb"><i class="fa-solid fa-gift"></i></div><div class="flex-grow-1"><strong><?= esc($item['product_name']) ?></strong><?php if ($item['variant']): ?><small class="d-block text-muted-brand">Type: <?= esc($item['variant']) ?></small><?php endif; ?></div><input class="form-control quantity-control" type="number" min="1" max="10" name="quantities[<?= esc($item['product_id']) ?>]" value="<?= esc($item['quantity']) ?>" aria-label="Quantity"><strong>₱<?= number_format($item['line_total'], 2) ?></strong><button class="btn border-0" type="submit" formaction="/cart/remove" name="product_id" value="<?= esc($item['product_id']) ?>" aria-label="Remove <?= esc($item['product_name']) ?>"><i class="fa-regular fa-trash-can"></i></button></div><?php endforeach; ?><div class="p-3 text-end"><button class="btn btn-outline-brand btn-sm" type="submit">Update cart</button></div></form><?php endif; ?></div></div><div class="col-lg-4"><div class="surface-card summary-card"><h2 class="h4">Order summary</h2><div class="d-flex justify-content-between py-3 border-bottom"><span>Subtotal</span><strong>₱<?= number_format($total, 2) ?></strong></div><div class="d-flex justify-content-between py-3"><span>Shipping</span><span>Calculated at checkout</span></div><div class="d-flex justify-content-between fs-5 py-3 border-top"><strong>Total</strong><strong>₱<?= number_format($total, 2) ?></strong></div><?php if ($items !== []): ?><a class="btn btn-brand w-100" href="/checkout">Check out</a><?php endif; ?></div></div></div></div></section>
<?= view('components/page_end') ?>
